    <livewire:chat-window />
    <script>
        document.addEventListener('alpine:init',()=>{Alpine.data('voiceInput',()=>({listening:false,recognition:null,lastInputWasVoice:false,init(){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R)return;this.recognition=new R;this.recognition.lang=document.documentElement.lang||navigator.language||'en-US';this.recognition.interimResults=false;this.recognition.onresult=e=>{this.lastInputWasVoice=true;this.$wire.set('input',e.results[0][0].transcript).then(()=>this.$wire.send())};this.recognition.onend=()=>this.listening=false;this.recognition.onerror=()=>this.listening=false;window.addEventListener('reply-received',()=>this.lastInputWasVoice&&this.speakLatestReply())},toggle(){if(!this.recognition)return alert(@json(__('Voice input is not supported in this browser.')));this.listening?this.recognition.stop():this.recognition.start();this.listening=!this.listening},speakLatestReply(){this.lastInputWasVoice=false;if(!window.speechSynthesis)return;const b=document.querySelectorAll('[data-message-role="assistant"]'),last=b[b.length-1];if(!last)return;const u=new SpeechSynthesisUtterance(last.innerText);u.lang=document.documentElement.lang||navigator.language;speechSynthesis.cancel();speechSynthesis.speak(u)}}))});
    </script>
